CH = dict(num=8, tag="Geography (Part 2)", theme="Maps, oceans, continents, landforms and human impact on the environment",
 title="World Geography: Some Glimpses",
 intro="A quick tour of our blue planet: how maps show the round Earth on flat paper, what lies in the oceans, and the mountains, plateaus, plains and deserts of each continent. Along the way we see how human actions disturb these natural features.",
 big_questions=["What are the unique physical features of the continents?", "Why do we need to understand world geography?", "How do human actions trigger environmental issues?"],
 blocks=[
 ("h2", "Mapping the Earth"),
 ("p", "The Earth is an **oblate spheroid**: nearly spherical, bulging at the equator and flattened at the poles. Drawing it on a flat map therefore always causes some **distortion** (think of laying a peeled orange flat). A **cartographer** is a person who draws or produces maps."),
 ("table", ["Colour on a physical map", "Shows"], [["Blue", "Water bodies: oceans, seas, lakes, rivers"], ["Green", "Plains"], ["Yellow / brown", "Plateaus"], ["Dark brown", "High mountains"], ["Light yellow", "Deserts"], ["White", "Ice and glaciers"]]),
 ("table", ["Projection", "What it does well", "Limitation"], [["Mercator", "Keeps shape and direction, so useful for navigation", "Distorts size near the poles (Greenland looks as big as Africa)"], ["Robinson", "Compromise between size and shape distortion; looks realistic", "Still not perfect"]]),
 ("note", "NOTE", "Professionals use **latitude and longitude** coordinates for precise locations, because every flat map projection is only approximate."),
 ("h2", "The Blue of the Blue Planet: The Oceans"),
 ("ul", ["Oceans cover about **71 per cent** of the Earth’s surface and hold **97 per cent** of its water; hence the name ‘blue planet’.", "They absorb and slowly release heat and add moisture to the air, so they help **regulate climate** and bring rainfall.", "Plankton (tiny organisms that float and make food by photosynthesis) give us almost **half the oxygen** we breathe.", "The ocean floor has mountains, valleys and plains like the land."]),
 ("table", ["Ocean", "Key features"], [["Pacific", "Largest and deepest; whales and tuna"], ["Atlantic", "One of the busiest waterways for trade; rich fishing ground"], ["Indian", "Warm waters, rich biodiversity, historically important for trade"], ["Arctic", "Smallest and shallowest; sea ice; polar bears and walruses"], ["Southern", "Encircles Antarctica; penguins and seals"]]),
 ("h3", "Currents, trenches and reefs"),
 ("ul", ["**Ocean currents** are giant river-like flows. **Warm currents** carry water from the equator to the poles; **cold currents** carry it from the poles towards the equator.", "The **Gulf Stream** carries warm water towards Western Europe, making the United Kingdom warmer than other places at the same latitude.", "**Trenches** are deep V-shaped areas. The **Mariana Trench** is deepest; its Challenger Deep is over 11,000 m below sea level, more than 2,000 m deeper than Everest is high. With no light, life there uses **energy from chemicals**.", "A **reef** is a ridge at or near the sea surface. Coral reefs are the **‘rainforests of the sea’**: they shelter about one-quarter of all ocean species.", "The **Great Barrier Reef** (north-east Australia) is about 2,000 km long, covers about 350,000 sq km and is a UNESCO World Heritage Site. **Coral bleaching** (caused largely by human actions changing ocean chemistry) kills coral and destroys habitat."]),
 ("h3", "Smaller water bodies"),
 ("table", ["Type", "Meaning", "Example"], [["Sea", "Large, partly enclosed saltwater area connected to an ocean", "Arabian Sea"], ["Gulf", "Large inlet of the sea cutting deeply into land", "Persian Gulf"], ["Bay", "Smaller, broad inlet of the sea", "Bay of Bengal"], ["Strait", "Narrow channel joining two seas or oceans", "Strait of Malacca"], ["Canal", "Man-made channel connecting water bodies", "Suez Canal"]]),
 ("p", "The **Suez Canal** (opened 1869) joins the Red Sea and the Mediterranean and is the shortest sea route from India to Europe. The **Bay of Bengal** is the world’s largest bay; bays give ports safe shelter from strong winds."),
 ("h2", "The Continents: Variety on Land"),
 ("p", "There are seven continents: Africa, Antarctica, Asia, Australia, Europe, North America and South America. Four landforms recur: **mountains** (high, broad base, steep slopes, narrow summit), **plateaus** (raised, flat top, steep sides), **plains** (extensive flat or gently rolling land) and **deserts** (less than 25 cm rain a year)."),
 ("h3", "Asia"),
 ("ul", ["**Tibetan Plateau:** highest and largest plateau; about 2,500 km by 1,000 km, average height over 4,500 m. Formed by the collision of the Indo-Australian and Eurasian plates. It is the ‘Third Pole’ (largest fresh-water store outside the poles) and the source of the **Indus, Brahmaputra and Yangtze**.", "**Gobi Desert** (Mongolia and north China): ‘Land of the Eternal Blue Sky’ with 8–9 months of sun, winters down to minus 30°C; herders move seasonally.", "**Eurasian Steppes:** flat, unforested grassland over 8,000 km; a **carbon sink**; resting place of the Siberian crane; nomads live in yurts.", "**Ural Mountains:** about 2,500 km long; boundary between Europe and Asia; taiga forests, tundra and **permafrost** (frozen soil that releases greenhouse gases when it melts); rich in iron ore, copper, coal, oil and gas."]),
 ("note", "DEFINITION", "**Water towers:** mountains are called water towers because snow and glaciers on them melt to supply fresh water to rivers."),
 ("h3", "Europe"),
 ("ul", ["**Great European Plain:** fertile, with wheat, barley, rye and potatoes; rivers help trade; supports cities like Paris, Berlin, Moscow, Warsaw.", "**Alps:** crescent-shaped, about 1,200 km; Mont Blanc; edelweiss (national flower of Austria); feed the Rhine and Danube; tourism and hydropower."]),
 ("h3", "Africa"),
 ("ul", ["**Sahara:** largest hot desert; rainfall under 25 cm; oases, date palms, nomads with camels; adaptations such as the fennec fox’s large ears and cacti storing water.", "**Savannah:** tropical grassland between rainforest and desert; elephants, lions, zebras, giraffes; threatened by farming and deforestation.", "**Nile:** longest river (about 6,650 km); cradle of ancient Egyptian civilisation; gives irrigation, water, fish, power and transport."]),
 ("h3", "South America"),
 ("ul", ["**Andes:** largest mountain range of the continent; Aconcagua (highest in the Western Hemisphere); Uyuni (largest salt flat); source of the Amazon; copper, zinc, silver, lithium. Only about one-fourth of the original flora and fauna remains: a **conservation hotspot**.", "**Amazon:** world’s largest river by volume; the rainforest is the ‘Lungs of the Earth’; about 400 indigenous communities; threatened by deforestation.", "**Atacama Desert** (Chile): about 1,000 km, one of the driest places; clear skies; now a dump for discarded **fast-fashion** clothes."]),
 ("h3", "North America and Australia"),
 ("ul", ["**Colorado Plateau:** over 330,000 sq km, Grand Canyon cut in layers of rock by erosion; about 5 million visitors a year.", "**Rockies** (about 4,800 km) hold copper, gold and silver; Yellowstone shows ecosystem restoration: wolves introduced in 1995 reduced overgrazing elk.", "**Appalachians:** among the oldest ranges; coal, timber, gas. **Great Lakes:** five large fresh-water lakes used for shipping and drinking water.", "**Australia:** much of it is desert (Great Australian Desert, Great Victoria Desert); the Spinifex people have lived there for over 25,000 years.", "**Antarctica** is the largest desert on Earth (over 14 million sq km) and the coldest."]),
 ("h2", "Humans and the Environment"),
 ("ul", ["Landforms shape **climate, settlement, farming and trade**.", "Human actions such as **deforestation, overuse of resources and pollution** cause desertification, biodiversity loss and climate change.", "Studying world geography helps us manage resources wisely for **sustainable development**."]),
 ("qa", [("Why does every flat map distort the Earth?", "Because the Earth is a nearly spherical oblate spheroid; flattening it stretches size, shape or direction."), ("Why is the Tibetan Plateau called the Third Pole?", "It holds the largest fresh-water reserves outside the polar regions."), ("Why are coral reefs called the rainforests of the sea?", "They shelter about one-quarter of ocean species and are rich in biodiversity."), ("What made the Great Lakes and the Nile important?", "Both supply water and transport; the Nile gave Egypt its civilisation."), ("How did wolves restore Yellowstone?", "They reduced the overgrazing elk, so plants returned.")]),
 ],
 takeaways=["Every flat map distorts the round Earth; Mercator keeps shape and direction, Robinson is a compromise.", "Oceans cover 71% of the Earth, hold 97% of its water, supply oxygen and regulate climate.", "Each continent has signature landforms: Tibetan Plateau, Gobi, Urals, Alps, Sahara, Nile, Andes, Amazon, Rockies, Great Barrier Reef.", "Human actions threaten these features; sustainable use is the answer."])
